ee:variables.ee:set-variable:
%dw 2.0
output application/json
var weekday= (vars."inventoryDate" as Date {format: "d-MMM-yyyy"}) 
				as String {format: "EEEE"}

---
{
    "Date": vars."inventoryDate",
    "weekday": weekday,
    "A1002":vars.tisTankrawData."00215" default 0,
    "A1003":vars.tisTankrawData."00216" default 0,
    "A1004":vars.tisTankrawData."00217" default 0,
    "A1005":vars.tisTankrawData."00435" default 0,
    "A1006":round(vars.invForfrp.C1004[0]  + vars.invForfrp.C1005[0] + vars.invForfrp.C1011[0] ) default 0,
  	//c1004+c1005+c1011
	"A1007":round(vars.invForfrp.C1019[0] default 0),
	//c1019
	"A1008":round(vars.invForfrp.C1007[0] default 0),
	//c10017
	"A1009":round(vars.invForfrp.C1042[0]-vars.invForfrp.C1037[0] default 0),
	//c1042-c1037
	"A1010":-(round(vars.invForfrp.C1040[0] default 0)),
	//c1040
	"A1011":round(vars.invForfrp.C1046[0] default 0),
	//c1046
	"A1012":(round(vars.invForfrp.C1051[0] default 0)),
	//c1051
	"A1013":round(vars.invForfrp.C1050[0] default 0),
	//c1050
	"A1014":round(vars.invForfrp.C1045[0] default 0),
	//c1045
	"A1015":round(vars.invForfrp.C1061[0] default 0)
	//c1061
}

%dw 2.0
output application/json
var formulas = vars."inventoryReplacedFormulas"
var date=vars.inventoryDate
var data =
    if (vars.invOrBreakoutTableName == p('freepointBreakout.tableName'))
        vars.assemblyProductsdata
    else if(vars.invOrBreakoutTableName == p('inventory.tableName'))
        vars.inventoryProductsData
    else
         "not assembly table or inv table"
---
formulas map (row) ->
  row map (cell) ->
    if (cell startsWith "=") cell
    else if (cell == "Formulas-Column") date
    // else if (cell == "Date") 
        //(data.Date as Date { format: "d-MMM-yyyy" }) as String { format: "dd-MMM-yyyy" }
   // else if (cell == "weekday") 
       // data.weekday 
    else if (data[cell]? != null) data[cell]
    else cell
